import * as T from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
import {EffectComposer} from './vendor/postprocessing/EffectComposer.js';
import {UnrealBloomPass} from './vendor/postprocessing/UnrealBloomPass.js';
import {SMAAPass} from './vendor/postprocessing/SMAAPass.js';
import {OutputPass} from './vendor/postprocessing/OutputPass.js';
import {N8AOPass} from './vendor/N8AO.js';
import {createPlaza} from './plaza.js';

const $=s=>document.querySelector(s),host=$('#world'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let renderer;try{renderer=new T.WebGLRenderer({antialias:true,powerPreference:'high-performance'});}catch(e){$('#load-status').textContent='请使用支持 WebGL 的浏览器并开启硬件加速。';throw e;}
renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.autoUpdate=false;renderer.shadowMap.needsUpdate=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;host.appendChild(renderer.domElement);renderer.domElement.tabIndex=0;renderer.domElement.setAttribute('aria-label','三维城堡广场。拖动画面环顾，WASD或方向键行走。');
const scene=new T.Scene();scene.fog=new T.FogExp2('#a9c4d6',.0024);const camera=new T.PerspectiveCamera(50,1,.15,1600);camera.rotation.order='YXZ';
const controls=new OrbitControls(camera,renderer.domElement);controls.enabled=false;controls.enableDamping=true;controls.dampingFactor=.08;controls.minDistance=45;controls.maxDistance=240;controls.maxPolarAngle=Math.PI*.47;controls.minPolarAngle=.06;controls.target.set(0,12,12);
const composer=new EffectComposer(renderer),ao=new N8AOPass(scene,camera,1280,720);ao.configuration.aoRadius=1.2;ao.configuration.distanceFalloff=.8;ao.configuration.intensity=1.1;ao.configuration.gammaCorrection=false;ao.configuration.color=new T.Color('#203646');ao.setQualityMode('Medium');composer.addPass(ao);const bloom=new UnrealBloomPass(new T.Vector2(1280,720),.2,.4,1.1);composer.addPass(bloom);composer.addPass(new SMAAPass());composer.addPass(new OutputPass());
let plaza,high=true,aerial=false,flight=null,t=0,previous=0,value=.45,targetTime=.45,drag=null,notification,walkView='promenade';const keys=new Set(),look=new T.Vector3();
const views={promenade:{name:'城堡前广场',position:[18,2.05,88],target:[0,25,-6]},bridge:{name:'城堡桥畔',position:[4,2.6,36],target:[0,27,-6]},garden:{name:'花园步道',position:[-34,2.05,77],target:[0,24,-6]}};
function notice(text){clearTimeout(notification);$('#notice').textContent=text;$('#notice').hidden=false;notification=setTimeout(()=>$('#notice').hidden=true,4000);}
function atView(name,instant=false){const v=views[name];walkView=name;aerial=false;controls.enabled=false;$('#aerial').setAttribute('aria-pressed','false');$('#crosshair').style.display='';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===name));$('#location-name').textContent=v.name;const p=new T.Vector3(...v.position),target=new T.Vector3(...v.target);camera.fov=host.clientWidth<620?62:50;camera.updateProjectionMatrix();if(instant||reduced){camera.position.copy(p);camera.lookAt(target);flight=null;}else{look.set(0,0,-1).applyQuaternion(camera.quaternion).multiplyScalar(100).add(camera.position);flight={from:camera.position.clone(),to:p,lookFrom:look.clone(),lookTo:target,start:performance.now(),duration:1800};}}
function setAerial(on){aerial=on;flight=null;keys.clear();controls.enabled=on;$('#aerial').setAttribute('aria-pressed',String(on));$('#crosshair').style.display=on?'none':'';if(on){camera.position.set(67,61,118);controls.target.set(0,12,21);controls.update();$('#location-name').textContent='城堡与花园 · 鸟瞰';}else atView(walkView);}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>atView(b.dataset.view));$('#aerial').onclick=()=>setAerial(!aerial);$('#home').onclick=()=>atView('promenade');$('#info').onclick=()=>{const on=$('#help').hidden;$('#help').hidden=!on;$('#info').setAttribute('aria-expanded',String(on));};
function setTime(v,instant=false){targetTime=T.MathUtils.clamp(v,0,1);if(instant)value=targetTime;$('#time').value=targetTime;document.querySelectorAll('[data-time]').forEach(b=>b.classList.toggle('selected',Math.abs(Number(b.dataset.time)-targetTime)<.09));$('#time-name').textContent=targetTime<.2?'晴朗日光':targetTime<.58?'日落之前':targetTime<.85?'蓝调时刻':'城堡星夜';}
document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>setTime(Number(b.dataset.time)));$('#time').oninput=e=>setTime(Number(e.target.value),true);
$('#quality').onclick=()=>{high=!high;$('#quality').textContent=high?'高画质':'流畅';$('#quality').setAttribute('aria-pressed',String(high));renderer.setPixelRatio(Math.min(devicePixelRatio,high?1.5:1));ao.setQualityMode(high?'Medium':'Low');plaza?.setQuality(high);resize();notice(high?'已开启高画质':'已减少草叶和阴影开销');};
$('#show').onclick=()=>{if(!plaza)return;setTime(1);atView('promenade');camera.fov=62;camera.updateProjectionMatrix();plaza.fireworks(t+1.5);notice('夜幕降临，烟花即将开始');};
const canvas=renderer.domElement;canvas.addEventListener('pointerdown',e=>{if(aerial||e.button!==0)return;flight=null;drag={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);canvas.focus({preventScroll:true});});canvas.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id||aerial)return;camera.rotation.y-=(e.clientX-drag.x)*.0028;camera.rotation.x=T.MathUtils.clamp(camera.rotation.x-(e.clientY-drag.y)*.0028,-1.2,1.25);camera.rotation.z=0;drag.x=e.clientX;drag.y=e.clientY;});const end=e=>{if(drag?.id===e.pointerId)drag=null;};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);canvas.addEventListener('wheel',e=>{if(aerial)return;e.preventDefault();camera.fov=T.MathUtils.clamp(camera.fov+e.deltaY*.025,32,72);camera.updateProjectionMatrix();},{passive:false});canvas.addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#help').hidden=true;$('#info').setAttribute('aria-expanded','false');keys.clear();return;}if(['INPUT','TEXTAREA'].includes(document.activeElement.tagName))return;const allowed=['w','a','s','d','W','A','S','D','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Shift'];if(allowed.includes(e.key)){e.preventDefault();keys.add(e.key.toLowerCase());flight=null;}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();drag=null;});
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();keys.add(b.dataset.key.toLowerCase());b.setPointerCapture(e.pointerId);flight=null;};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key.toLowerCase());});
function walk(dt){if(aerial||!keys.size)return;const forward=Number(keys.has('w')||keys.has('arrowup'))-Number(keys.has('s')||keys.has('arrowdown')),right=Number(keys.has('d')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('arrowleft'));if(!forward&&!right)return;const a=camera.rotation.y,speed=(keys.has('shift')?7.5:3.8)*dt/Math.max(1,Math.hypot(forward,right)),x=camera.position.x+(-Math.sin(a)*forward+Math.cos(a)*right)*speed,z=camera.position.z+(-Math.cos(a)*forward-Math.sin(a)*right)*speed;if(z<16||z>147||Math.abs(x)>41)return;if(z<40&&Math.abs(x)>5.45)return;if(z>42&&z<141&&Math.abs(x)>9.1&&Math.abs(x)<30.9&&Math.hypot(x,z-76)>30.8&&Math.abs(z-48)>2&&Math.abs(z-104)>4)return;camera.position.x=x;camera.position.z=z;camera.position.y=T.MathUtils.lerp(camera.position.y,z<40?2.6:2.05,Math.min(dt*6,1));}
function resize(){const w=host.clientWidth,h=host.clientHeight;camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h);composer.setSize(w,h);$('#hint').textContent=w<620?'拖动环顾 · 按住箭头行走':'拖动环顾 · WASD 行走 · 滚轮调整视野';}new ResizeObserver(resize).observe(host);resize();atView('promenade',true);setTime(.45,true);
try{plaza=await createPlaza(renderer,scene,(n,total)=>{$('#load-progress').style.width=Math.min(94,8+n/Math.max(1,total)*84)+'%';$('#load-status').textContent='正在载入建筑与自然环境';});plaza.light(value);$('#load-progress').style.width='100%';$('#loading').remove();document.body.dataset.ready='true';canvas.focus({preventScroll:true});}catch(error){console.error(error);$('#load-status').textContent='场景资源加载遇到问题，请刷新重试。';document.body.dataset.error=String(error.message);throw error;}
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-previous)/1000,.05);previous=now;if(document.hidden)return;t+=dt;if(flight){const k=Math.min(1,(now-flight.start)/flight.duration),s=k*k*(3-2*k);camera.position.lerpVectors(flight.from,flight.to,s);look.lerpVectors(flight.lookFrom,flight.lookTo,s);camera.lookAt(look);if(k===1)flight=null;}walk(dt);if(aerial)controls.update(dt);value=T.MathUtils.lerp(value,targetTime,Math.min(1,dt*2.5));const night=plaza.light(value);bloom.strength=.06+night*.13;plaza.update(t,camera);$('#show').classList.toggle('active',plaza.showActive(t));composer.render(dt);}requestAnimationFrame(frame);
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();notice('画面暂时中断，请刷新页面。');});
if(document.modelContext?.registerTool){for(const tool of [{name:'read_castle_scene',description:'读取城堡漫游的时间、视角和观景位置。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({time:targetTime,aerial,view:walkView})},{name:'visit_castle_view',description:'前往广场、桥畔或花园观景位置。',inputSchema:{type:'object',properties:{view:{type:'string',enum:Object.keys(views)}},required:['view'],additionalProperties:false},execute:({view})=>{if(!views[view])throw Error('未知观景位置');atView(view);return{view};}},{name:'set_castle_time',description:'调整日光、暮色与星夜，0为白天，1为夜晚。',inputSchema:{type:'object',properties:{time:{type:'number',minimum:0,maximum:1}},required:['time'],additionalProperties:false},execute:({time})=>{if(!Number.isFinite(time)||time<0||time>1)throw Error('时间超出范围');setTime(time);return{time};}}])try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}

